typedef struct {
    int id;
    char name[32];
    double balance;
} Account;

typedef struct {
    int x;
    int y;
} Point;

typedef enum {
    LEVEL_DEBUG = 0,
    LEVEL_INFO = 1,
    LEVEL_WARN = 2,
    LEVEL_ERROR = 3
} LogLevel;

typedef enum {
    RED,
    GREEN,
    BLUE
} Color;

int count_chars(const char *s) {
    int n = 0;
    while (*s) { n++; s++; }
    return n;
}

void strcpy_safe(char *dst, const char *src, size_t n) {
    strncpy(dst, src, n - 1);
    dst[n - 1] = '\0';
}

int sum_array(const int *xs, size_t n) {
    int total = 0;
    for (size_t i = 0; i < n; i++) {
        total += xs[i];
    }
    return total;
}

int sum_matrix(int m[3][3]) {
    int total = 0;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            total += m[i][j];
    return total;
}

int *make_array(size_t n) {
    int *p = (int *)malloc(n * sizeof(int));
    if (p == NULL) return NULL;
    for (size_t i = 0; i < n; i++) p[i] = 0;
    return p;
}

char *dup_string(const char *s) {
    size_t n = strlen(s) + 1;
    char *out = (char *)malloc(n);
    if (out == NULL) return NULL;
    strcpy(out, s);
    return out;
}

int countdown(int n) {
    int steps = 0;
    do {
        n--;
        steps++;
    } while (n > 0);
    return steps;
}

int skip_whitespace(const char *s, int i) {
    do {
        i++;
    } while (s[i] == ' ');
    return i;
}

const char *level_name(int l) {
    switch (l) {
        case 0: return "debug";
        case 1: return "info";
        case 2: return "warn";
        case 3: return "error";
        default: return "unknown";
    }
}

int to_nibble(char c) {
    switch (c) {
        case '0'...'9': return c - '0';
        case 'a'...'f': return c - 'a' + 10;
        default: return -1;
    }
}

unsigned int pack_rgb(unsigned int r, unsigned int g, unsigned int b) {
    return ((r & 0xff) << 16) | ((g & 0xff) << 8) | (b & 0xff);
}

unsigned int low_byte(unsigned int v) {
    return v & 0xff;
}

int flags() {
    return 0xFF | 0xAB00;
}

int mask(int v) {
    return v & 0xFFFF;
}

int is_null(char c) {
    return c == '\0';
}

int is_newline(char c) {
    return c == '\n';
}

int account_id(Account *a) {
    return a->id;
}

void set_name(Account *a, const char *name) {
    strncpy(a->name, name, 31);
    a->name[31] = '\0';
}

int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

void zero_array(int *xs, size_t n) {
    for (size_t i = 0; i < n; i++) {
        xs[i] = 0;
    }
}

int strlen_manual(const char *s) {
    int n = 0;
    while (*s++) n++;
    return n;
}

void *make_node(int val) {
    Node *p = (Node *)malloc(sizeof(Node));
    p->val = val;
    p->next = NULL;
    return p;
}

int sum_n(int count, int *nums) {
    int total = 0;
    for (int i = 0; i < count; i++) total += nums[i];
    return total;
}

int next_id() {
    static int counter = 0;
    return ++counter;
}

int first_non_space(const char *s) {
    int i = 0;
    while (s[i] == ' ') i++;
    return i;
}

enum Direction {
    NORTH,
