    EAST,
    WEST
};

int byte_count(const int *xs, size_t n) {
    return n * sizeof(int);
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

int abs_val(int x) {
    return x < 0 ? -x : x;
}

const char *greet() {
    return "hello, world";
}

void dump(const char *label, int val) {
    printf("%s = %d\n", label, val);
}

void identity(int m[3][3]) {
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            m[i][j] = (i == j) ? 1 : 0;
}

Point origin() {
    Point p = {0, 0};
    return p;
}

int count_pairs(int *xs, size_t n) {
    int count = 0;
    for (size_t i = 0; i < n; i++)
        for (size_t j = i + 1; j < n; j++)
            if (xs[i] + xs[j] == 10) count++;
    return count;
}

int find_first(int *xs, size_t n, int target) {
    for (size_t i = 0; i < n; i++) {
        if (xs[i] == target) return (int)i;
    }
    return -1;
}

int read_file(const char *path, char *buf, size_t n) {
    FILE *f = fopen(path, "r");
    if (f == NULL) return -1;
    int r = (int)fread(buf, 1, n, f);
    fclose(f);
    return r;
}

double distance(double x1, double y1, double x2, double y2) {
    double dx = x1 - x2;
    double dy = y1 - y2;
    return sqrt(dx * dx + dy * dy);
}

unsigned int pack16(unsigned int hi, unsigned int lo) {
    return (hi << 8) | (lo & 0xff);
}

long long sum_to(long long n) {
    long long total = 0;
    for (long long i = 1; i <= n; i++) total += i;
    return total;
}

int count_set_bits(unsigned int x) {
    int count = 0;
    while (x) {
        count += x & 1;
        x >>= 1;
    }
    return count;
}
